export const BREATHING_EXCHANGE_GASES = [
  // ---- MCQ ----
  { id: 'bg-1', type: 'mcq', question: 'The exchange of O2 and CO2 between the atmosphere and body tissues, achieved via the respiratory system, is collectively called:', options: ['Cellular respiration', 'Breathing (external respiration)', 'Excretion', 'Circulation'], correctIndex: 1, explanation: 'Breathing/external respiration is the process of exchanging gases between the atmosphere and blood via the lungs.', difficulty: 'easy' },
  { id: 'bg-2', type: 'mcq', question: 'Air enters the respiratory system through the:', options: ['Trachea directly', 'External nostrils', 'Alveoli', 'Bronchioles'], correctIndex: 1, explanation: 'Air first enters through the external nostrils (nares) before passing further down the tract.', difficulty: 'easy' },
  { id: 'bg-3', type: 'mcq', question: 'The air passage common to both the digestive and respiratory systems is the:', options: ['Larynx', 'Pharynx', 'Trachea', 'Oesophagus'], correctIndex: 1, explanation: 'The pharynx is a shared passage for both air and food before they diverge into separate tracts.', difficulty: 'medium' },
  { id: 'bg-4', type: 'mcq', question: 'The voice box, containing the vocal cords, is called the:', options: ['Pharynx', 'Larynx', 'Trachea', 'Epiglottis'], correctIndex: 1, explanation: 'The larynx houses the vocal cords and is commonly called the voice box.', difficulty: 'easy' },
  { id: 'bg-5', type: 'mcq', question: 'The trachea divides into two primary bronchi, one for each lung, at a point called the:', options: ['Larynx', 'Carina', 'Alveolar duct', 'Pleura'], correctIndex: 1, explanation: 'The carina is the point where the trachea bifurcates into the right and left primary bronchi.', difficulty: 'medium' },
  { id: 'bg-6', type: 'mcq', question: 'The trachea, primary bronchi, and secondary bronchi are supported by rings/plates of which type of tissue, preventing their collapse?', options: ['Bone', 'Cartilage', 'Adipose tissue', 'Smooth muscle only'], correctIndex: 1, explanation: 'Cartilaginous rings support these airways, keeping them from collapsing during breathing.', difficulty: 'medium' },
  { id: 'bg-7', type: 'mcq', question: 'The functional, balloon-like structures where actual gas exchange occurs in the lungs are the:', options: ['Bronchioles', 'Alveoli', 'Primary bronchi', 'Trachea'], correctIndex: 1, explanation: 'Alveoli are thin-walled sacs where the actual exchange of O2 and CO2 takes place.', difficulty: 'easy' },
  { id: 'bg-8', type: 'mcq', question: 'The thin membrane separating the alveolar air from the blood in surrounding capillaries, allowing efficient gas exchange, is called the:', options: ['Pleura', 'Alveolar-capillary membrane', 'Epiglottis', 'Diaphragm'], correctIndex: 1, explanation: 'The alveolar-capillary membrane is the thin barrier across which gases diffuse.', difficulty: 'medium' },
  { id: 'bg-9', type: 'mcq', question: 'Each lung is covered by a double-layered membrane called the:', options: ['Pericardium', 'Peritoneum', 'Pleura', 'Meninges'], correctIndex: 2, explanation: 'The pleura is the double membrane covering each lung, with a fluid-filled space between the layers.', difficulty: 'easy' },
  { id: 'bg-10', type: 'mcq', question: 'The fluid present between the two pleural layers primarily serves to:', options: ['Provide nutrients to the lungs', 'Reduce friction during lung movement while breathing', 'Transport oxygen to the alveoli', 'Prevent gas exchange'], correctIndex: 1, explanation: 'Pleural fluid lubricates the pleural layers, minimising friction as the lungs expand/contract.', difficulty: 'medium' },
  { id: 'bg-11', type: 'mcq', question: 'The dome-shaped muscle separating the thoracic and abdominal cavities, essential for breathing, is the:', options: ['Diaphragm', 'Intercostal muscle', 'Larynx', 'Pleura'], correctIndex: 0, explanation: 'The diaphragm is a key muscle for breathing, separating the thoracic and abdominal cavities.', difficulty: 'easy' },
  { id: 'bg-12', type: 'mcq', question: 'During inspiration (inhalation), the diaphragm:', options: ['Relaxes and moves upward, decreasing thoracic volume', 'Contracts and moves downward, increasing thoracic volume', 'Remains completely stationary', 'Detaches from the ribcage'], correctIndex: 1, explanation: 'Diaphragm contraction (flattening/moving downward) increases thoracic volume, driving air inward.', difficulty: 'medium' },
  { id: 'bg-13', type: 'mcq', question: 'During inspiration, the external intercostal muscles:', options: ['Relax, causing ribs to move inward', 'Contract, lifting the ribs and sternum outward, increasing thoracic volume', 'Have no role in breathing at all', 'Only function during forced expiration'], correctIndex: 1, explanation: 'External intercostal contraction lifts the rib cage, expanding the thoracic cavity during inspiration.', difficulty: 'medium' },
  { id: 'bg-14', type: 'mcq', question: 'Air moves into the lungs during inspiration primarily because of a pressure gradient in which:', options: ['Pulmonary pressure becomes higher than atmospheric pressure', 'Pulmonary (intra-pulmonary) pressure becomes lower than atmospheric pressure', 'Both pressures remain exactly equal at all times', 'Pressure has no role in air movement'], correctIndex: 1, explanation: 'Inspiration occurs when the increase in thoracic volume lowers pulmonary pressure below atmospheric pressure, drawing air in.', difficulty: 'medium' },
  { id: 'bg-15', type: 'mcq', question: 'During quiet/normal expiration, the process is primarily achieved by:', options: ['Active, forceful contraction of expiratory muscles', 'Relaxation of the diaphragm and intercostal muscles, returning the thoracic cavity to its original size', 'Contraction of the diaphragm', 'An increase in thoracic volume'], correctIndex: 1, explanation: 'Normal expiration is largely a passive process driven by relaxation of the muscles that caused inspiration.', difficulty: 'medium' },
  { id: 'bg-16', type: 'mcq', question: 'The volume of air inspired or expired during normal, quiet breathing is called the:', options: ['Vital capacity', 'Tidal volume', 'Residual volume', 'Inspiratory reserve volume'], correctIndex: 1, explanation: 'Tidal volume is the amount of air moved in/out during a normal breath (~500 mL in a healthy adult).', difficulty: 'medium' },
  { id: 'bg-17', type: 'mcq', question: 'The additional volume of air that can be forcefully inspired beyond normal tidal inspiration is called the:', options: ['Expiratory reserve volume', 'Residual volume', 'Inspiratory reserve volume (IRV)', 'Functional residual capacity'], correctIndex: 2, explanation: 'IRV is the extra air that can be forcibly inhaled after a normal tidal inspiration.', difficulty: 'medium' },
  { id: 'bg-18', type: 'mcq', question: 'The additional volume of air that can be forcefully expired beyond normal tidal expiration is called the:', options: ['Inspiratory reserve volume', 'Expiratory reserve volume (ERV)', 'Residual volume', 'Vital capacity'], correctIndex: 1, explanation: 'ERV is the extra air that can be forcibly exhaled after a normal tidal expiration.', difficulty: 'medium' },
  { id: 'bg-19', type: 'mcq', question: 'The volume of air remaining in the lungs even after a forceful expiration is called the:', options: ['Tidal volume', 'Vital capacity', 'Residual volume', 'Inspiratory capacity'], correctIndex: 2, explanation: 'Residual volume is the air that always remains in the lungs, even after maximal forced exhalation.', difficulty: 'medium' },
  { id: 'bg-20', type: 'mcq', question: 'Vital capacity is defined as the sum of:', options: ['Tidal volume and residual volume only', 'IRV, tidal volume, and ERV (the maximum air exhaled after maximum inhalation)', 'Only the residual volume', 'Only the inspiratory reserve volume'], correctIndex: 1, explanation: 'Vital capacity = IRV + tidal volume + ERV, representing the maximum air exchanged in one breath cycle.', difficulty: 'medium' },
  { id: 'bg-21', type: 'mcq', question: 'The total lung capacity is defined as:', options: ['Vital capacity minus residual volume', 'Vital capacity plus residual volume', 'Tidal volume alone', 'IRV alone'], correctIndex: 1, explanation: 'Total lung capacity = vital capacity + residual volume, representing the full volume the lungs can hold.', difficulty: 'medium' },
  { id: 'bg-22', type: 'mcq', question: 'According to the diffusion of gases across the alveolar membrane, the direction of O2 movement is determined mainly by:', options: ['Active transport requiring ATP', 'The partial pressure gradient of O2 between alveolar air and blood', 'Random, non-directional movement', 'Temperature differences alone'], correctIndex: 1, explanation: 'Gases diffuse passively down their partial pressure gradients — O2 moves from alveolar air (higher pO2) into blood (lower pO2).', difficulty: 'medium' },
  { id: 'bg-23', type: 'mcq', question: 'Compared to O2, CO2 is generally considered to diffuse across the alveolar membrane:', options: ['Much more slowly than O2, despite a smaller pressure gradient', 'About 20-25 times faster than O2 for a given pressure gradient, due to higher solubility', 'At exactly the same rate as O2 always', 'Not at all, since CO2 cannot cross membranes'], correctIndex: 1, explanation: "CO2's higher solubility allows it to diffuse much faster than O2 despite a smaller partial pressure difference.", difficulty: 'hard' },
  { id: 'bg-24', type: 'mcq', question: 'Most of the oxygen transported in blood is carried:', options: ['Dissolved directly in plasma', 'Bound to haemoglobin in red blood cells, forming oxyhaemoglobin', 'As bicarbonate ions', 'Bound to plasma proteins other than haemoglobin'], correctIndex: 1, explanation: 'About 97% of oxygen is transported bound to haemoglobin as oxyhaemoglobin; only a small fraction dissolves directly in plasma.', difficulty: 'medium' },
  { id: 'bg-25', type: 'mcq', question: 'The graphical relationship between the partial pressure of oxygen and the percentage saturation of haemoglobin with oxygen is called the:', options: ['Starling curve', 'Oxygen dissociation curve', 'Action potential curve', 'Titration curve'], correctIndex: 1, explanation: 'The oxygen dissociation curve, sigmoid in shape, plots haemoglobin O2 saturation against pO2.', difficulty: 'medium' },
  { id: 'bg-26', type: 'mcq', question: 'The majority of carbon dioxide transported in the blood is carried in the form of:', options: ['Dissolved CO2 gas in plasma', 'Bicarbonate ions (HCO3-)', 'Carbaminohaemoglobin exclusively', 'Bound tightly and irreversibly to haemoglobin'], correctIndex: 1, explanation: 'The majority (around 70%) of CO2 is transported as bicarbonate ions in the plasma/RBCs.', difficulty: 'medium' },
  { id: 'bg-27', type: 'mcq', question: 'A smaller but significant fraction of CO2 is transported bound to haemoglobin, forming a compound called:', options: ['Oxyhaemoglobin', 'Carbaminohaemoglobin', 'Methaemoglobin', 'Carboxyhaemoglobin'], correctIndex: 1, explanation: 'Carbaminohaemoglobin forms when CO2 binds directly to haemoglobin (not at the O2-binding site).', difficulty: 'medium' },
  { id: 'bg-28', type: 'mcq', question: 'The enzyme responsible for catalysing the rapid conversion of CO2 and water into carbonic acid (which then dissociates into bicarbonate and H+) is:', options: ['Amylase', 'Carbonic anhydrase', 'Pepsin', 'Catalase'], correctIndex: 1, explanation: 'Carbonic anhydrase, abundant in RBCs, speeds up the CO2 + H2O ⇌ H2CO3 ⇌ HCO3- + H+ reaction.', difficulty: 'medium' },
  { id: 'bg-29', type: 'mcq', question: 'The primary rhythm-generating centre for breathing, located in the brain, is found in the:', options: ['Cerebrum', 'Medulla oblongata', 'Cerebellum', 'Hypothalamus'], correctIndex: 1, explanation: 'The respiratory rhythm centre in the medulla oblongata sets the basic breathing rhythm.', difficulty: 'medium' },
  { id: 'bg-30', type: 'mcq', question: 'The pneumotaxic centre, which can moderate the function of the medullary respiratory centre and reduce inspiratory duration, is located in the:', options: ['Pons region of the brain', 'Cerebellum', 'Spinal cord', 'Hypothalamus'], correctIndex: 0, explanation: 'The pneumotaxic centre in the pons can send signals to fine-tune (reduce) inspiration duration.', difficulty: 'medium' },
  { id: 'bg-31', type: 'mcq', question: 'The chemosensitive area, sensitive to changes in CO2 and hydrogen ion concentration, plays a role in regulating breathing and is located:', options: ['Adjacent to the rhythm centre in the medulla', 'In the retina', 'In the liver', 'In the kidney only'], correctIndex: 0, explanation: 'The chemosensitive area near the medullary rhythm centre detects CO2/H+ changes and signals the rhythm centre to adjust breathing.', difficulty: 'medium' },
  { id: 'bg-32', type: 'mcq', question: 'Among the changes detected to regulate respiration, the body is generally MORE sensitive to changes in:', options: ['Oxygen concentration alone', 'CO2 concentration and hydrogen ion (pH) concentration in the blood', 'Only body temperature', 'Only atmospheric pressure'], correctIndex: 1, explanation: 'The respiratory control system is more responsive to CO2/H+ changes than to O2 concentration changes, within normal ranges.', difficulty: 'medium' },
  { id: 'bg-33', type: 'mcq', question: 'Specialised receptors sensitive to blood CO2 and H+ levels, located near the aorta and carotid arteries, are called:', options: ['Chemoreceptors', 'Baroreceptors', 'Photoreceptors', 'Osmoreceptors'], correctIndex: 0, explanation: 'Chemoreceptors near major arteries detect changes in blood CO2/H+ levels, feeding information to the respiratory centres.', difficulty: 'medium' },
  { id: 'bg-34', type: 'mcq', question: 'Asthma, a common respiratory disorder, is characterised by:', options: ['Permanent destruction of alveolar walls', 'Difficulty in breathing caused by inflammation and narrowing of bronchi and bronchioles', 'Excess oxygen in the blood', 'A bacterial infection of the pleura only'], correctIndex: 1, explanation: 'Asthma involves inflammation and constriction of the airways, causing breathing difficulty.', difficulty: 'easy' },
  { id: 'bg-35', type: 'mcq', question: 'Emphysema, a chronic respiratory disorder often linked to smoking, involves:', options: ['Increased elasticity of alveolar walls', 'Damage/destruction of alveolar walls, decreasing respiratory surface area', 'Excess mucus production only, with no structural damage', 'Complete absence of any lung damage'], correctIndex: 1, explanation: 'Emphysema damages alveolar walls, reducing the surface area available for gas exchange.', difficulty: 'medium' },
  { id: 'bg-36', type: 'mcq', question: 'Occupational respiratory disorders, such as silicosis, are commonly caused by:', options: ['Long-term exposure to excess oxygen only', 'Long-term exposure to irritant dust/particles (e.g., silica dust) in certain workplace environments', 'Only viral infections', 'Only allergies unrelated to occupation'], correctIndex: 1, explanation: 'Occupational lung diseases like silicosis result from prolonged inhalation of harmful dust particles at the workplace.', difficulty: 'medium' },
  { id: 'bg-37', type: 'mcq', question: 'The percentage of atmospheric air composed of oxygen is approximately:', options: ['78%', '20.9%', '0.04%', '50%'], correctIndex: 1, explanation: 'Oxygen makes up roughly 20.9% of atmospheric air by volume.', difficulty: 'easy' },
  { id: 'bg-38', type: 'mcq', question: 'The percentage of atmospheric air composed of nitrogen is approximately:', options: ['20.9%', '0.04%', '78%', '99%'], correctIndex: 2, explanation: 'Nitrogen constitutes roughly 78% of atmospheric air.', difficulty: 'easy' },
  { id: 'bg-39', type: 'mcq', question: 'A structure called the epiglottis functions to:', options: ['Produce sound in the larynx', 'Prevent food from entering the trachea during swallowing', 'Filter dust from inhaled air', 'Warm incoming air'], correctIndex: 1, explanation: 'The epiglottis covers the glottis (opening to trachea) during swallowing, preventing food from entering the airway.', difficulty: 'medium' },
  { id: 'bg-40', type: 'mcq', question: 'The mucus and cilia lining much of the respiratory tract serve mainly to:', options: ['Produce vocal sound', 'Trap and remove dust particles/microbes and help filter incoming air', 'Increase oxygen absorption directly', 'Regulate breathing rate'], correctIndex: 1, explanation: 'Mucus traps particles/microbes, while cilia sweep them out — a key air-filtering mechanism.', difficulty: 'medium' },
  { id: 'bg-41', type: 'mcq', question: 'The number of alveoli in human lungs is estimated to be around:', options: ['A few hundred', 'A few thousand', 'About 300 million', 'About 3 million'], correctIndex: 2, explanation: 'Human lungs contain an estimated 300 million alveoli, providing a huge surface area for gas exchange.', difficulty: 'medium' },
  { id: 'bg-42', type: 'mcq', question: 'A key reason the huge number of alveoli is significant for respiratory efficiency is that it:', options: ['Reduces the total surface area for gas exchange', 'Massively increases the total surface area available for gas exchange', 'Has no functional significance', 'Only matters for sound production'], correctIndex: 1, explanation: 'The enormous alveolar surface area (about 80 sq. metres total) enables efficient, rapid gas exchange.', difficulty: 'medium' },
  { id: 'bg-43', type: 'mcq', question: 'The normal breathing rate in a healthy resting human adult is approximately:', options: ['1–2 breaths per minute', '12–16 breaths per minute', '40–50 breaths per minute', '100 breaths per minute'], correctIndex: 1, explanation: 'A healthy resting adult typically breathes about 12–16 times per minute.', difficulty: 'medium' },
  { id: 'bg-44', type: 'mcq', question: 'Hyperventilation (unusually rapid, deep breathing) can lead to excessive loss of which gas from the blood?', options: ['Oxygen', 'Carbon dioxide', 'Nitrogen', 'Helium'], correctIndex: 1, explanation: 'Hyperventilation excessively expels CO2, potentially lowering blood CO2 below normal levels.', difficulty: 'medium' },
  { id: 'bg-45', type: 'mcq', question: 'Which of the following best describes the relationship between ventilation (breathing rate/depth) and gas exchange efficiency?', options: ['Ventilation has no relationship to gas exchange at all', 'Adequate ventilation ensures sufficient fresh air reaches alveoli, maintaining favourable partial pressure gradients for efficient gas exchange', 'Only expiration matters for gas exchange, not inspiration', 'Gas exchange occurs independent of any airflow'], correctIndex: 1, explanation: 'Proper ventilation maintains the partial pressure gradients that drive efficient gas exchange at the alveoli.', difficulty: 'medium' },
  { id: 'bg-46', type: 'mcq', question: "The term 'external respiration' most specifically refers to:", options: ['Cellular oxidation of glucose to release energy', 'Exchange of O2 and CO2 between the atmosphere/alveoli and the blood', 'Excretion of nitrogenous waste', 'Nerve impulse transmission'], correctIndex: 1, explanation: 'External respiration specifically means the gas exchange occurring at the lungs/alveoli, distinct from cellular respiration.', difficulty: 'medium' },
  { id: 'bg-47', type: 'mcq', question: 'Compared to external respiration, cellular respiration refers to:', options: ['The same exact process occurring at the alveoli', 'Oxidative breakdown of food molecules within cells to release energy, utilising O2 and producing CO2', 'Only the physical act of breathing', 'A process that occurs exclusively in the lungs'], correctIndex: 1, explanation: 'Cellular respiration is the intracellular oxidative breakdown of nutrients using O2 and releasing CO2 as a byproduct — distinct from breathing itself.', difficulty: 'medium' },
  { id: 'bg-48', type: 'mcq', question: 'A decrease in blood pH (increased acidity), often linked to rising CO2 levels, generally causes the respiratory centre to:', options: ['Decrease the rate and depth of breathing', 'Increase the rate and depth of breathing to expel more CO2', 'Have no effect on breathing at all', 'Immediately stop breathing altogether'], correctIndex: 1, explanation: 'Increased CO2/acidity stimulates the respiratory centre to increase ventilation, helping expel excess CO2.', difficulty: 'medium' },
  { id: 'bg-49', type: 'mcq', question: "Which of the following would most directly reduce the respiratory (alveolar) surface area available for gas exchange, as seen in emphysema?", options: ['Increased number of alveoli', 'Destruction and merging of alveolar walls into fewer, larger air spaces', 'Increased pleural fluid only', 'Thickening of the epiglottis'], correctIndex: 1, explanation: 'In emphysema, alveolar walls break down and merge, reducing the total number of small alveoli and the overall surface area.', difficulty: 'medium' },
  { id: 'bg-50', type: 'mcq', question: 'Which of the following best summarises the overall purpose of the respiratory system?', options: ['To produce digestive enzymes', 'To facilitate exchange of O2 and CO2 between the environment and body tissues, supporting cellular respiration', 'To filter blood cells exclusively', 'To regulate body temperature only'], correctIndex: 1, explanation: 'The respiratory system exists fundamentally to enable gas exchange that supports cellular energy metabolism throughout the body.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'bg-ar-1', type: 'assertion-reason', question: 'Assertion (A): The pharynx serves as a common passage for both air and food.\nReason (R): The pharynx connects to both the oesophagus (digestive tract) and the larynx (respiratory tract).', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "This dual connection is exactly why the pharynx serves both digestive and respiratory functions.", difficulty: 'medium' },
  { id: 'bg-ar-2', type: 'assertion-reason', question: 'Assertion (A): The trachea does not collapse despite continuous airflow.\nReason (R): The trachea is supported by cartilaginous rings that maintain its shape.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'The structural support from cartilage rings is exactly what prevents tracheal collapse.', difficulty: 'medium' },
  { id: 'bg-ar-3', type: 'assertion-reason', question: 'Assertion (A): Alveoli are the primary sites of gas exchange in the lungs.\nReason (R): Alveoli have extremely thick walls that slow down gas diffusion.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true, but R is false — alveolar walls are actually extremely THIN, which speeds up (not slows down) gas diffusion.', difficulty: 'medium' },
  { id: 'bg-ar-4', type: 'assertion-reason', question: 'Assertion (A): Inspiration occurs when pulmonary pressure becomes lower than atmospheric pressure.\nReason (R): Contraction of the diaphragm and external intercostal muscles increases thoracic cavity volume.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Increased thoracic volume from these muscle contractions directly causes the pressure drop that drives inspiration.', difficulty: 'medium' },
  { id: 'bg-ar-5', type: 'assertion-reason', question: 'Assertion (A): Normal, quiet expiration is largely a passive process.\nReason (R): It occurs mainly due to relaxation of the diaphragm and intercostal muscles, allowing elastic recoil of the lungs.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Muscle relaxation and elastic recoil are exactly why quiet expiration requires little active muscular effort.', difficulty: 'medium' },
  { id: 'bg-ar-6', type: 'assertion-reason', question: 'Assertion (A): Vital capacity includes the residual volume.\nReason (R): Vital capacity is the sum of inspiratory reserve volume, tidal volume, and expiratory reserve volume.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Vital capacity does NOT include residual volume (A is false) — it is defined as IRV + tidal volume + ERV, as R correctly states; residual volume is added separately to get total lung capacity.', difficulty: 'medium' },
  { id: 'bg-ar-7', type: 'assertion-reason', question: 'Assertion (A): CO2 diffuses across the alveolar membrane much faster than O2 for a given partial pressure gradient.\nReason (R): CO2 has a much higher solubility than O2 in the relevant biological fluids/membranes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "CO2's greater solubility is exactly why it diffuses so much faster than O2 despite similar or smaller pressure gradients.", difficulty: 'hard' },
  { id: 'bg-ar-8', type: 'assertion-reason', question: 'Assertion (A): Most oxygen in the blood is transported dissolved directly in plasma.\nReason (R): Oxygen has very high solubility in plasma, making haemoglobin unnecessary for its transport.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 3, explanation: 'Both are false — most O2 is actually transported bound to haemoglobin (not dissolved in plasma), precisely because O2 has LOW solubility in plasma, making haemoglobin essential.', difficulty: 'medium' },
  { id: 'bg-ar-9', type: 'assertion-reason', question: 'Assertion (A): The majority of CO2 in blood is transported as bicarbonate ions.\nReason (R): Carbonic anhydrase catalyses the rapid conversion of CO2 and water into carbonic acid, which dissociates into bicarbonate and H+.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'This enzymatic conversion pathway is exactly what allows most CO2 to be transported as bicarbonate.', difficulty: 'medium' },
  { id: 'bg-ar-10', type: 'assertion-reason', question: 'Assertion (A): The respiratory rhythm centre is located in the cerebrum.\nReason (R): The cerebrum directly controls the basic, involuntary rhythm of breathing at all times.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 3, explanation: 'Both are false — the respiratory rhythm centre is actually located in the medulla oblongata, not the cerebrum.', difficulty: 'medium' },
  { id: 'bg-ar-11', type: 'assertion-reason', question: 'Assertion (A): The pneumotaxic centre can reduce the duration of inspiration.\nReason (R): The pneumotaxic centre is located in the pons and can moderate the function of the medullary rhythm centre.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "This moderating influence from the pons-based pneumotaxic centre is exactly how inspiration duration gets adjusted.", difficulty: 'medium' },
  { id: 'bg-ar-12', type: 'assertion-reason', question: 'Assertion (A): The body\'s respiratory control system responds more strongly to changes in oxygen levels than to CO2/H+ changes.\nReason (R): Chemosensitive areas near the medulla and chemoreceptors near major arteries are especially responsive to CO2 and H+ changes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The system is actually MORE sensitive to CO2/H+ than O2 changes (A is false, since it claims the opposite); R correctly describes the CO2/H+-focused sensitivity of these detectors.', difficulty: 'medium' },
  { id: 'bg-ar-13', type: 'assertion-reason', question: 'Assertion (A): Asthma is characterised by narrowing of the bronchi and bronchioles.\nReason (R): Inflammation in asthma causes airway constriction, making breathing difficult.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Inflammation-driven airway constriction is exactly the mechanism underlying asthma\'s characteristic breathing difficulty.', difficulty: 'medium' },
  { id: 'bg-ar-14', type: 'assertion-reason', question: 'Assertion (A): Emphysema increases the total surface area available for gas exchange.\nReason (R): Emphysema involves destruction of alveolar walls, causing smaller alveoli to merge into fewer, larger air spaces.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Emphysema actually DECREASES (not increases) the surface area for gas exchange (A is false); R correctly explains why — fewer, larger air spaces mean less total surface area.', difficulty: 'medium' },
  { id: 'bg-ar-15', type: 'assertion-reason', question: 'Assertion (A): Silicosis is an occupational respiratory disorder.\nReason (R): It results from long-term exposure to silica dust particles in certain work environments.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: 'Prolonged occupational exposure to silica dust is exactly why silicosis is classified as an occupational disorder.', difficulty: 'medium' },
  { id: 'bg-ar-16', type: 'assertion-reason', question: 'Assertion (A): Cellular respiration and external respiration (breathing) refer to exactly the same process.\nReason (R): External respiration is gas exchange at the alveoli, while cellular respiration is the oxidative breakdown of nutrients within cells.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'These are actually two DIFFERENT processes, not the same one (A is false); R correctly distinguishes between them.', difficulty: 'medium' },
  { id: 'bg-ar-17', type: 'assertion-reason', question: 'Assertion (A): An increase in blood CO2/acidity generally increases the rate and depth of breathing.\nReason (R): This response, via the chemosensitive area and rhythm centre, helps expel excess CO2 from the body.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "Expelling excess CO2 via increased ventilation is exactly the purpose and outcome of this regulatory response.", difficulty: 'medium' },
  { id: 'bg-ar-18', type: 'assertion-reason', question: 'Assertion (A): The huge number of alveoli in human lungs provides a very large surface area for gas exchange.\nReason (R): A larger surface area generally increases the efficiency of diffusion-based gas exchange.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "Greater surface area enhancing diffusion efficiency is exactly why having millions of alveoli benefits gas exchange.", difficulty: 'medium' },
  { id: 'bg-ar-19', type: 'assertion-reason', question: 'Assertion (A): The epiglottis prevents air from entering the lungs during breathing.\nReason (R): The epiglottis covers the glottis specifically during swallowing, to prevent food from entering the trachea.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "The epiglottis actually prevents FOOD (not air) from entering the trachea, and only during swallowing (A is false); R correctly describes its real function.", difficulty: 'medium' },
  { id: 'bg-ar-20', type: 'assertion-reason', question: 'Assertion (A): Haemoglobin\'s affinity for oxygen is influenced by factors like pO2, pCO2, H+ concentration, and temperature.\nReason (R): These factors shift the position of the oxygen dissociation curve, affecting how readily haemoglobin binds or releases oxygen.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'Both A and R are false'], correctIndex: 0, explanation: "This shifting of the dissociation curve is exactly the mechanism by which these factors modulate haemoglobin's O2 affinity.", difficulty: 'hard' },

  // ---- Statement-based ----
  { id: 'bg-st-1', type: 'statement', question: 'Statement I: The pharynx is common to both the digestive and respiratory pathways.\nStatement II: The larynx contains the vocal cords.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the pharynx and larynx.', difficulty: 'easy' },
  { id: 'bg-st-2', type: 'statement', question: 'Statement I: The trachea and bronchi are supported by bony rings.\nStatement II: These structures are supported by cartilaginous rings/plates.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the support is cartilaginous, not bony, as correctly stated in Statement II.', difficulty: 'medium' },
  { id: 'bg-st-3', type: 'statement', question: 'Statement I: Alveoli are the sites of actual gas exchange in the lungs.\nStatement II: The alveolar-capillary membrane is thick, slowing gas exchange.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — the membrane is extremely THIN, which speeds up, not slows, gas exchange.', difficulty: 'medium' },
  { id: 'bg-st-4', type: 'statement', question: 'Statement I: During inspiration, the diaphragm contracts and moves downward.\nStatement II: This contraction decreases thoracic cavity volume.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — diaphragm contraction actually INCREASES thoracic volume, not decreases it.', difficulty: 'medium' },
  { id: 'bg-st-5', type: 'statement', question: 'Statement I: Normal quiet expiration is largely a passive process.\nStatement II: Forced expiration involves active contraction of additional expiratory muscles.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish passive quiet expiration from active forced expiration.', difficulty: 'medium' },
  { id: 'bg-st-6', type: 'statement', question: 'Statement I: Tidal volume is the air moved during normal, quiet breathing.\nStatement II: Vital capacity is smaller than tidal volume.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — vital capacity is much LARGER than tidal volume, not smaller.', difficulty: 'medium' },
  { id: 'bg-st-7', type: 'statement', question: 'Statement I: Residual volume is the air that always remains in the lungs, even after maximum forced expiration.\nStatement II: Total lung capacity equals vital capacity plus residual volume.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly define residual volume and total lung capacity.', difficulty: 'medium' },
  { id: 'bg-st-8', type: 'statement', question: 'Statement I: Oxygen diffuses from alveolar air into blood because alveolar pO2 is lower than blood pO2.\nStatement II: CO2 diffuses from blood into alveolar air because blood pCO2 is higher than alveolar pCO2.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — alveolar pO2 is actually HIGHER (not lower) than blood pO2, driving O2 into the blood; Statement II correctly describes CO2 movement.', difficulty: 'medium' },
  { id: 'bg-st-9', type: 'statement', question: 'Statement I: Most oxygen is transported bound to haemoglobin as oxyhaemoglobin.\nStatement II: A small fraction of oxygen is transported dissolved directly in plasma.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the two modes of oxygen transport in blood.', difficulty: 'medium' },
  { id: 'bg-st-10', type: 'statement', question: 'Statement I: Most CO2 in the blood is transported as bicarbonate ions.\nStatement II: A significant fraction of CO2 is also transported bound to haemoglobin as carbaminohaemoglobin.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the major and minor pathways of CO2 transport.', difficulty: 'medium' },
  { id: 'bg-st-11', type: 'statement', question: 'Statement I: Carbonic anhydrase slows down the conversion of CO2 and water into carbonic acid.\nStatement II: Carbonic anhydrase is abundant in red blood cells.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — carbonic anhydrase actually SPEEDS UP (not slows) this reaction; Statement II is correct.', difficulty: 'medium' },
  { id: 'bg-st-12', type: 'statement', question: 'Statement I: The respiratory rhythm centre is located in the medulla oblongata.\nStatement II: The pneumotaxic centre is located in the pons and can moderate the rhythm centre\'s function.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly identify the locations of these two breathing-regulation centres.', difficulty: 'medium' },
  { id: 'bg-st-13', type: 'statement', question: 'Statement I: The respiratory system is more sensitive to changes in oxygen levels than to CO2/H+ levels.\nStatement II: Chemoreceptors near the aorta and carotid arteries detect changes in blood CO2 and H+ levels.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — sensitivity to CO2/H+ is actually GREATER than to O2; Statement II correctly describes the role of these chemoreceptors.', difficulty: 'medium' },
  { id: 'bg-st-14', type: 'statement', question: 'Statement I: Asthma involves narrowing of the airways due to inflammation.\nStatement II: Emphysema involves destruction of alveolar walls, reducing gas exchange surface area.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe these two distinct respiratory disorders.', difficulty: 'medium' },
  { id: 'bg-st-15', type: 'statement', question: 'Statement I: Silicosis is caused by a viral infection of the lungs.\nStatement II: Silicosis is an occupational disorder caused by long-term inhalation of silica dust.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — silicosis is caused by dust inhalation, not a virus; Statement II correctly describes its actual cause.', difficulty: 'medium' },
  { id: 'bg-st-16', type: 'statement', question: 'Statement I: External respiration refers to gas exchange between the atmosphere and blood.\nStatement II: Cellular respiration refers to the oxidative breakdown of nutrients within cells.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly distinguish external respiration from cellular respiration.', difficulty: 'medium' },
  { id: 'bg-st-17', type: 'statement', question: 'Statement I: Oxygen makes up approximately 20.9% of atmospheric air.\nStatement II: Nitrogen makes up approximately 78% of atmospheric air.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both figures correctly describe the composition of atmospheric air.', difficulty: 'easy' },
  { id: 'bg-st-18', type: 'statement', question: 'Statement I: Human lungs contain roughly 300 million alveoli.\nStatement II: This large number provides a massive surface area for gas exchange.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe alveolar number and its functional significance.', difficulty: 'medium' },
  { id: 'bg-st-19', type: 'statement', question: 'Statement I: A normal resting adult breathes about 12–16 times per minute.\nStatement II: Hyperventilation involves an unusually slow, shallow breathing pattern.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — hyperventilation involves unusually RAPID, deep breathing, not slow/shallow.', difficulty: 'medium' },
  { id: 'bg-st-20', type: 'statement', question: 'Statement I: The pleura is a double-layered membrane covering each lung.\nStatement II: Pleural fluid reduces friction between the pleural layers during breathing movements.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the pleura and the function of pleural fluid.', difficulty: 'easy' },

  // ---- "How many of the following are correct" ----
  { id: 'bg-hm-1', type: 'statement', question: 'How many of the following are correctly part of the human respiratory tract pathway (in general anatomical order)?\nExternal nostrils, Pharynx, Larynx, Trachea, Bronchi, Bronchioles, Alveoli', options: ['Four', 'Five', 'Six', 'All seven'], correctIndex: 3, explanation: 'All seven listed structures are genuine, sequential components of the human respiratory tract.', difficulty: 'medium' },
  { id: 'bg-hm-2', type: 'statement', question: 'How many of the following are true regarding pulmonary volumes?\nTidal volume is the air moved in normal breathing, IRV is extra air that can be forcibly inhaled, ERV is extra air that can be forcibly exhaled, Residual volume can be completely expelled with maximum effort', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; residual volume, by definition, CANNOT be completely expelled even with maximum effort.', difficulty: 'medium' },
  { id: 'bg-hm-3', type: 'statement', question: 'How many of the following are involved in generating the pressure gradient for normal inspiration?\nDiaphragm contraction, External intercostal muscle contraction, Increase in thoracic cavity volume, Increase in pulmonary pressure above atmospheric pressure', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three are correct; pulmonary pressure actually DECREASES below atmospheric pressure during inspiration, not increases above it.', difficulty: 'medium' },
  { id: 'bg-hm-4', type: 'statement', question: 'How many of the following are true regarding oxygen transport in blood?\nMost O2 is bound to haemoglobin as oxyhaemoglobin, A small fraction dissolves in plasma, The oxygen dissociation curve is sigmoid in shape, Haemoglobin\'s O2 affinity is unaffected by pCO2 or pH', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; haemoglobin\'s O2 affinity IS in fact affected by pCO2, pH, and temperature.', difficulty: 'hard' },
  { id: 'bg-hm-5', type: 'statement', question: 'How many of the following are correct pathways/forms of CO2 transport in blood?\nAs bicarbonate ions, As carbaminohaemoglobin, Dissolved directly in plasma (a smaller fraction), As oxyhaemoglobin', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Bicarbonate, carbaminohaemoglobin, and dissolved CO2 are all genuine CO2 transport forms; oxyhaemoglobin is an O2-carrying form, unrelated to CO2 transport.', difficulty: 'medium' },
  { id: 'bg-hm-6', type: 'statement', question: 'How many of the following are involved in the regulation of respiration?\nRespiratory rhythm centre (medulla), Pneumotaxic centre (pons), Chemosensitive area near the medulla, Chemoreceptors near the aorta/carotid arteries', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are genuine components involved in regulating breathing.', difficulty: 'medium' },
  { id: 'bg-hm-7', type: 'statement', question: 'How many of the following are respiratory disorders?\nAsthma, Emphysema, Silicosis, Osteoporosis', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Asthma, emphysema, and silicosis are respiratory disorders; osteoporosis is a bone disorder, unrelated to breathing.', difficulty: 'medium' },
  { id: 'bg-hm-8', type: 'statement', question: 'How many of the following statements about emphysema are correct?\nIt is often linked to smoking, It destroys alveolar walls, It decreases the surface area for gas exchange, It increases lung elasticity', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; emphysema actually DECREASES (not increases) lung elasticity.', difficulty: 'medium' },
  { id: 'bg-hm-9', type: 'statement', question: 'How many of the following gases/values are correctly matched to their approximate atmospheric percentage?\nOxygen — 20.9%, Nitrogen — 78%, Carbon dioxide — 0.04%, Nitrogen — 20.9%', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three matches are correct; the fourth incorrectly assigns nitrogen the oxygen percentage.', difficulty: 'medium' },
  { id: 'bg-hm-10', type: 'statement', question: 'How many of the following structures play a role in preventing collapse or protecting the airway during breathing/swallowing?\nCartilaginous rings in the trachea, The epiglottis, Mucus and cilia lining the tract, The residual volume of air', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Cartilaginous rings, the epiglottis, and mucus/cilia all serve protective/structural roles; residual volume is simply a lung air volume measure, not a protective structure.', difficulty: 'medium' },
];
